function populateUnitOptions(reset){var type=document.getElementById('unitType'),from=document.getElementById('unitFrom'),to=document.getElementById('unitTo');if(!type||!from||!to)return;var group=UNIT_GROUPS[type.value]||UNIT_GROUPS.length,defaults=UNIT_DEFAULTS[type.value]||UNIT_DEFAULTS.length,oldFrom=from.value,oldTo=to.value;function options(sel,want){sel.innerHTML=group.map(function(u){return '<option value="'+E(u[0])+'">'+E(u[1])+'</option>'}).join('');var valid=group.some(function(u){return u[0]===want});sel.value=(!reset&&valid)?want:(group.some(function(u){return u[0]===defaults[0]})?defaults[0]:group[0][0]);}options(from,oldFrom);options(to,oldTo);if(reset){from.value=defaults[0];to.value=defaults[1];}if(from.value===to.value&&group.length>1){to.value=group[1][0];}}
function unitToBase(value,group,unit){if(group==='temperature'){if(unit==='C')return value+273.15;if(unit==='F')return (value+459.67)*5/9;return value;}var item=(UNIT_GROUPS[group]||[]).filter(function(u){return u[0]===unit})[0];return item?value*item[2]:NaN;}
function unitFromBase(value,group,unit){if(group==='temperature'){if(unit==='C')return value-273.15;if(unit==='F')return value*9/5-459.67;return value;}var item=(UNIT_GROUPS[group]||[]).filter(function(u){return u[0]===unit})[0];return item?value/item[2]:NaN;}
function unitNumber(n){if(!Number.isFinite(n))return '—';if(n===0)return '0';var a=Math.abs(n);return a>=1e9||a<1e-6?Number(n).toExponential(6):String(Number(n.toPrecision(10)));}
